-- sql-08 完整示例：事务边界 / 条件更新 / 幂等（sql.js，SQLite 3.35+）
-- SQLite 只有单写者，没有行锁与间隙锁；死锁与隔离级别的差异见文末注释。

PRAGMA foreign_keys = ON;
PRAGMA busy_timeout = 5000;   -- 撞锁时等待 5 秒，而不是立刻 SQLITE_BUSY

DROP TABLE IF EXISTS accounts;
CREATE TABLE accounts (
  id      INTEGER PRIMARY KEY,
  name    TEXT    NOT NULL,
  balance INTEGER NOT NULL CHECK (balance >= 0)
);
INSERT INTO accounts (id, name, balance) VALUES (1, 'alice', 600), (2, 'bob', 400);

DROP TABLE IF EXISTS stock;
CREATE TABLE stock (
  sku TEXT    PRIMARY KEY,
  qty INTEGER NOT NULL CHECK (qty >= 0)
);
INSERT INTO stock (sku, qty) VALUES ('T-100', 1);

DROP TABLE IF EXISTS orders;
CREATE TABLE orders (
  id       INTEGER PRIMARY KEY,
  user_id  INTEGER NOT NULL,
  amount   INTEGER NOT NULL,
  idem_key TEXT    NOT NULL UNIQUE   -- 幂等键由客户端生成
);

-- ① 正确的转账：条件更新 + 同一事务内判断受影响行数
BEGIN IMMEDIATE;
UPDATE accounts SET balance = balance - 100
 WHERE id = 1 AND balance >= 100;   -- getRowsModified() = 1，检查与扣减原子完成
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;
-- 结果：alice 500，bob 500，总额仍为 1000

-- ② 余额不足：受影响行数为 0，必须 ROLLBACK 而不是 COMMIT
BEGIN IMMEDIATE;
UPDATE accounts SET balance = balance - 9999
 WHERE id = 1 AND balance >= 9999;  -- getRowsModified() = 0
ROLLBACK;                           -- 若这里 COMMIT，就会留下半截状态

-- ③ 防超卖：库存判断写进 WHERE，用受影响行数判断是否抢到
BEGIN IMMEDIATE;
UPDATE stock SET qty = qty - 1 WHERE sku = 'T-100' AND qty > 0;
COMMIT;                             -- getRowsModified() = 1 抢到，= 0 售罄

-- ④ 幂等：唯一索引 + 冲突忽略，重复请求不报错也不多插
INSERT INTO orders (user_id, amount, idem_key)
VALUES (101, 9900, 'req-20260301-0001')
ON CONFLICT(idem_key) DO NOTHING;   -- 第一次 getRowsModified() = 1

INSERT INTO orders (user_id, amount, idem_key)
VALUES (101, 9900, 'req-20260301-0001')
ON CONFLICT(idem_key) DO NOTHING;   -- 第二次 getRowsModified() = 0，视为成功

-- ⑤ 验证：总额守恒、库存不为负、订单只有一行
SELECT (SELECT SUM(balance) FROM accounts) AS total_balance;  -- 1000
SELECT qty FROM stock WHERE sku = 'T-100';                    -- 0
SELECT COUNT(*) FROM orders;                                  -- 1
SELECT id, name, balance FROM accounts ORDER BY id;           -- 1 alice 500 / 2 bob 500

-- ⑥ 死锁只在有行锁的数据库里能复现（SQLite 没有）：
--   MySQL：会话 A BEGIN; UPDATE ... WHERE id=1;  会话 B BEGIN; UPDATE ... WHERE id=2;
--          然后 A 去更新 id=2、B 去更新 id=1 → ERROR 1213 (40001): Deadlock found
--   PG：  ERROR: deadlock detected (SQLSTATE 40P01)
--   排查：MySQL 看 SHOW ENGINE INNODB STATUS 的 LATEST DETECTED DEADLOCK；PG 看日志。

-- ⑦ 同一段逻辑在三家的隔离行为：
--   MySQL InnoDB 默认 REPEATABLE READ：快照读 + next-key lock，当前读会加间隙锁；
--   PostgreSQL 默认 READ COMMITTED：SERIALIZABLE 下冲突报 40001，业务必须重试；
--   SQLite 默认 SERIALIZABLE：文件锁 + WAL，写全局串行，冲突表现为 SQLITE_BUSY。

quiz.q:
`accounts` 中 alice 初始余额为 600。依次执行下面语句后，alice 的余额是多少（SQLite）？

```sql
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1 AND balance >= 100;
UPDATE accounts SET balance = balance - 9999 WHERE id = 1 AND balance >= 9999;
COMMIT;
```

导出脚本在业务高峰期漏了数据，核心循环如下。最可能的原因是什么？

```js
for (let offset = 0; ; offset += 1000) {
  const rows = db.exec(`SELECT * FROM orders ORDER BY id LIMIT 1000 OFFSET ${offset}`)
  if (!rows.length) break
  write(rows)
}
```
